/* ===== Legal Documents & Compliance – screens and actions ===== */
const lcQ = () => (App.ui.lcQ || '').toLowerCase();
function lcSub(id) { if (!id) return null; const U = lcUnits(), S = new Set([id]); let grew = true; while (grew) { grew = false; U.forEach(u => { if (!S.has(u.id) && S.has(u.parent)) { S.add(u.id); grew = true; } }); } return S; }
const lcSelUnit = () => { const mine = lcUnitsMine(); const u = App.ui.lcUnit; if (u && mine.includes(u)) return u; if (!lcCentral()) { const br = lcUnits().filter(x => x.type === 'Branch' && mine.includes(x.id)); return br.length === 1 ? br[0].id : ''; } return ''; };
const lcUnitSel = () => { const mine = new Set(lcUnitsMine()), U = lcUnits(), sel = lcSelUnit(), selU = lcU(sel); /* institution level = entity or institution that contains the selection */ let inst = ''; { let x = selU; for (let k = 0; x && x.id && k < 6; k++) { if (x.type === 'Entity' || x.type === 'Institution') { inst = x.id; break; } x = lcU(x.parent); } } const ents = U.filter(u => u.type === 'Entity'); const opt = (u, label) => `<option value="${u.id}" ${inst === u.id ? 'selected' : ''}>${esc(label || u.name)}</option>`; let h = `<option value="" ${!sel ? 'selected' : ''}>${lcCentral() ? 'All institutions (group)' : 'All my units'}</option>`; ents.forEach(e => { const kids = U.filter(u => u.type === 'Institution' && u.parent === e.id && (mine.has(u.id) || U.some(b => b.type === 'Branch' && b.parent === u.id && mine.has(b.id)))); if (!kids.length && !mine.has(e.id)) return; h += `<optgroup label="${esc(e.name)} (${e.entityType})">${mine.has(e.id) ? opt(e, e.name + ' – entity level') : ''}${kids.map(k => opt(k)).join('')}</optgroup>`; }); const instSel = `<label class="fld"><span>Society / institution</span><select data-act="uiSel" data-k="lcUnit">${h}</select></label>`; /* branch selector: branches inside the selected institution (or all mine), grouped by zone */ const sub = inst ? lcSub(inst) : null; const brs = U.filter(u => u.type === 'Branch' && mine.has(u.id) && !u.closed && (!sub || sub.has(u.id))); const zones = [...new Set(brs.map(b => b.district))]; const bsel = selU.type === 'Branch' ? sel : ''; const bh = `<option value="${inst && !bsel ? inst : ''}" ${!bsel ? 'selected' : ''}>${brs.length === 1 ? brs[0].name : `All branches (${brs.length})`}</option>${zones.map(z => `<optgroup label="${esc(z)}">${brs.filter(b => b.district === z).map(b => `<option value="${b.id}" ${bsel === b.id ? 'selected' : ''}>${esc(b.name)}</option>`).join('')}</optgroup>`).join('')}`; const brSel = `<label class="fld"><span>Branch</span><select data-act="uiSel" data-k="lcUnit">${bh}</select></label>`; return instSel + brSel; };
const lcBar = (extra = '', opts = {}) => `<div class="srf-strip2">${lcUnitSel()}${opts.noSearch ? '' : `<label class="fld grow"><span>Search</span><input data-act="uiInput" data-k="lcQ" id="lcQ" value="${esc(App.ui.lcQ || '')}" placeholder="${esc(opts.ph || 'Requirement, reference no., authority, branch…')}"></label>`}${extra}</div>`;
function lcRows() { const sub = lcSub(lcSelUnit()), q = lcQ(), st = App.ui.lcSt || '', cat = App.ui.lcCat || ''; return lcItems().filter(i => lcVisible(i) && (!sub || sub.has(i.unit)) && (!cat || lcCat(i.cat).group === cat) && (!st || (st === 'FLAG' ? lcFlags(i).length > 0 : lcStatus(i) === st)) && (!q || `${i.name} ${i.refNo} ${lcAuthN(i.authority)} ${lcPath(lcU(i.unit))} ${lcCat(i.cat).name}`.toLowerCase().includes(q))); }
const lcNoAccess = () => lcp('view') ? '' : '<div class="note bad"><b>Legal Documents &amp; Compliance</b> is restricted to Legal, Principal / branch HR, Finance, management and audit roles.</div>';
const lcDaysCell = i => { const d = lcDue(i); if (!d) return '—'; const n = lcDays(d); return `<span class="${n < 0 ? 'red' : n <= 30 ? 'amber' : ''}">${n < 0 ? -n + ' d ago' : n === 0 ? 'today' : n + ' d'}</span>`; };
const LC_COLS = () => [{ h: 'Requirement', k: i => `<b>${esc(i.name)}</b><div class="small muted">${esc(lcCat(i.cat).group)} · ${esc(lcCat(i.cat).name)}</div>`, t: 'html', x: i => i.name }, { h: 'Institution / unit', k: i => { const u = lcU(i.unit); return `${esc(u.name)}<div class="small muted">${esc(u.type)}${u.parent && lcU(u.parent).name ? ' · ' + esc(lcU(u.parent).name) : ''}</div>`; }, t: 'html', x: i => lcShort(lcU(i.unit)) }, { h: 'Ref. no.', k: i => i.refNo || '—', t: 'text', cls: 'small' }, { h: 'Expiry / due', k: i => (lcDue(i) ? bkDate(lcDue(i)) : '—') + (i.dateVerified ? '' : lcDue(i) ? ' <span class="small amber">(unverified)</span>' : ''), t: 'html', x: i => lcDue(i) || '' }, { h: 'Days', k: lcDaysCell, t: 'html', x: i => lcDue(i) ? lcDays(lcDue(i)) : 99999 }, { h: 'Status', k: i => lcPill(lcStatus(i)), t: 'html', x: i => lcStatus(i) }, { h: 'Flags', k: i => lcFlags(i).map(f => `<span class="pill warn">${esc(f)}</span>`).join(' ') || '', t: 'html', x: i => lcFlags(i).join(', ') }, { h: 'Owner', k: i => i.owner, t: 'text', cls: 'small' }];
/* ---------- dashboard ---------- */
PAGES.lc_home = { title: 'Legal Documents & Compliance', mod: 'lc_home', render() { const g = lcNoAccess(); if (g) return g; lcRun(); const I = lcRows(), A = I.filter(i => i.applic === 'Applicable'), st = i => lcStatus(i); const cur = A.filter(i => ['Valid', 'On record', 'Renewed', 'Submitted'].includes(st(i))).length, lapsed = A.filter(lcLapsed), due = A.filter(i => st(i) === 'Due Soon'), tasks = LCT().tasks.filter(t => !['Closed', 'Cancelled'].includes(t.status) && I.some(i => i.id === t.item)), review = I.filter(i => st(i) === 'Needs Review' || i.naReq), flagged = A.filter(i => lcFlags(i).length), sub = lcSub(lcSelUnit()), cases = LCT().cases.filter(c => !c.deleted && lcUnitsMine().includes(c.unit) && (!sub || sub.has(c.unit)) && !/Closed|Settled|Disposed/.test(c.status)); const pct = A.length ? Math.round(cur / A.length * 100) : 100; const kp = `<div class="kpis k7">${bkKpi('Compliance', `<span class="${pct >= 90 ? 'green' : pct >= 75 ? 'amber' : 'red'}">${pct}%</span>`, `${cur} current of ${A.length} applicable`)}${bkKpi('Expired / overdue', `<span class="${lapsed.length ? 'red' : 'green'}">${lapsed.length}</span>`, 'renew or file now')}${bkKpi('Due soon', `<span class="${due.length ? 'amber' : 'green'}">${due.length}</span>`, 'within reminder window')}${bkKpi('Tasks in progress', tasks.length, `${tasks.filter(t => t.status === 'Legal review').length} in legal review · ${tasks.filter(t => t.status === 'Fee approval').length} fee approval`)}${bkKpi('Needs Legal review', `<span class="${review.length ? 'amber' : 'green'}">${review.length}</span>`, 'applicability, date or N/A request to confirm')}${bkKpi('Missing / unverified / incomplete', `<span class="${flagged.length ? 'amber' : 'green'}">${flagged.length}</span>`, 'date, document or verification missing')}${bkKpi('Open legal matters', `<span class="${cases.length ? 'amber' : 'green'}">${cases.length}</span>`, `${cases.filter(c => c.type === 'Notice').length} notices · ${cases.filter(c => c.type === 'Case').length} cases`)}</div>`; const popup = LCM().cfg.popup && lapsed.length ? `<div class="note bad"><b>${lapsed.length} document${lapsed.length === 1 ? ' is' : 's are'} expired or overdue.</b> ${lapsed.slice(0, 3).map(i => esc(i.name + ' · ' + lcShort(lcU(i.unit)))).join('; ')}${lapsed.length > 3 ? ' …' : ''}</div>` : ''; const next = A.filter(i => lcDue(i) && lcDays(lcDue(i)) >= 0 && lcDays(lcDue(i)) <= 30).sort((a, b) => lcDue(a).localeCompare(lcDue(b))); const ev = lcEvents().filter(e => e.kind === 'Hearing' || e.kind === 'Notice reply').filter(e => lcDays(e.date) <= 30); const byBr = {}; A.forEach(i => { const b = lcBranchOf(lcU(i.unit)) || (lcU(i.unit).type === 'Entity' ? lcU(i.unit).name : 'Group'); const o = byBr[b] = byBr[b] || { k: b, n: 0, cur: 0, lapsed: 0, due: 0, flags: 0 }; o.n++; if (['Valid', 'On record', 'Renewed', 'Submitted'].includes(st(i))) o.cur++; if (lcLapsed(i)) o.lapsed++; if (st(i) === 'Due Soon') o.due++; if (lcFlags(i).length) o.flags++; }); const brRows = Object.values(byBr).sort((a, b) => (a.cur / a.n) - (b.cur / b.n)); const addBtn = lcp('edit') ? `<button class="btn primary" data-act="lcAddForm">Add item</button>` : ''; return `${lcBar(`<div class="btnrow">${addBtn}</div>`, { noSearch: true })}${popup}${kp}<div class="grid2"><div>${card('Next 30 days', table('lcNext', [{ h: 'Date', k: i => bkDate(lcDue(i)), t: 'text', x: i => lcDue(i) }, { h: 'Requirement', k: i => `${esc(i.name)}<div class="small muted">${esc(lcShort(lcU(i.unit)))}</div>`, t: 'html', x: i => i.name }, { h: 'Status', k: i => lcPill(st(i)), t: 'html', x: st }, { h: 'Owner', k: i => i.owner, t: 'text', cls: 'small' }], next, { rowAct: 'lcOpen', rowKey: i => i.id, compact: true, limit: 15, empty: 'Nothing due in the next 30 days.' }) + (ev.length ? `<p class="small"><b>Hearings &amp; notice replies:</b> ${ev.map(e => `${bkDate(e.date)} · ${esc(e.title)}`).join(' · ')}</p>` : ''))}</div><div>${card('Expired and overdue', table('lcLapsed', [{ h: 'Overdue', k: i => `<span class="red">${-lcDays(lcDue(i))} d</span>`, t: 'html', x: i => lcDays(lcDue(i)) }, { h: 'Requirement', k: i => `${esc(i.name)}<div class="small muted">${esc(lcShort(lcU(i.unit)))}</div>`, t: 'html', x: i => i.name }, { h: 'Task', k: i => { const t = lcTask(i); return t ? lcPill(t.status) : (lcp('task') ? `<button class="btn sm" data-act="lcStartTask" data-k="${esc(i.id)}">Start</button>` : '—'); }, t: 'html', noexp: true }, { h: 'Owner', k: i => i.owner, t: 'text', cls: 'small' }], lapsed.sort((a, b) => lcDue(a).localeCompare(lcDue(b))), { rowAct: 'lcOpen', rowKey: i => i.id, compact: true, limit: 15, empty: 'Nothing expired or overdue.' }))}</div></div>${card('Compliance by institution', table('lcByBr', [{ h: 'Institution / entity', k: r => /^B\d/.test(r.k) ? hrBr(r.k) : r.k, t: 'text' }, { h: 'Applicable', k: r => r.n, t: 'num' }, { h: 'Current', k: r => r.cur, t: 'num' }, { h: 'Compliance', k: r => Math.round(r.cur / r.n * 100), t: 'pct', rc: r => r.cur / r.n < 0.75 ? 'red' : r.cur / r.n < 0.9 ? 'amber' : 'green' }, { h: 'Expired / overdue', k: r => r.lapsed, t: 'num', rc: r => r.lapsed ? 'red' : '' }, { h: 'Due soon', k: r => r.due, t: 'num' }, { h: 'Flags', k: r => r.flags, t: 'num' }], brRows, { compact: true, limit: 60 }), { right: exportBtns('lcByBr', 'lc_home'), sub: 'Compliance = documents that are valid, on record, renewed or submitted ÷ applicable documents. Items marked not applicable (with Legal Admin approval) are excluded.' })}`; } };
/* ---------- register ---------- */
PAGES.lc_register = { title: 'Legal Document Register', mod: 'lc_register', render() { const g = lcNoAccess(); if (g) return g; const groups = [...new Set(LCM().cats.map(c => c.group))]; const extra = `<label class="fld"><span>Status</span><select data-act="uiSel" data-k="lcSt"><option value="">All statuses</option><option value="FLAG" ${App.ui.lcSt === 'FLAG' ? 'selected' : ''}>Flagged (missing / unverified)</option>${LC_STATUS.map(s => `<option ${App.ui.lcSt === s ? 'selected' : ''}>${s}</option>`).join('')}</select></label><label class="fld"><span>Category</span><select data-act="uiSel" data-k="lcCat"><option value="">All categories</option>${groups.map(s => `<option ${App.ui.lcCat === s ? 'selected' : ''}>${esc(s)}</option>`).join('')}</select></label><div class="btnrow">${lcp('edit') ? `<button class="btn primary" data-act="lcAddForm">Add item</button>` : ''}</div>`; const rows = lcRows().sort((a, b) => (lcDue(a) || '9999').localeCompare(lcDue(b) || '9999')); return `${lcBar(extra)}${card(`Register · ${rows.length} items`, table('lcReg', LC_COLS(), rows, { rowAct: 'lcOpen', rowKey: i => i.id, compact: true, limit: 100 }), { right: exportBtns('lcReg', 'lc_register'), sub: 'One row per requirement per unit (entity, institution, branch, building or vehicle). Dates must be verified by Legal before reminders are relied on; documents are versioned on every renewal.' })}`; } };
function lcItemDoc(i) { const u = lcU(i.unit), r = lcReq(i.req), st = lcStatus(i), t = lcTask(i), T = LCT(), ed = lcp('edit'), kind = (r || {}).kind || i.kind; const row = (k, vv) => `<tr><th>${k}</th><td>${vv == null || vv === '' ? '—' : vv}</td></tr>`; const flags = lcFlags(i); const info = `<table class="kv"><tbody>${row('Unit', esc(lcPath(u)))}${row('Category', esc(lcCat(i.cat).group + ' › ' + lcCat(i.cat).name))}${row('Kind', esc(kind + ' – ' + (LC_KIND[kind] || '')))}${row('Frequency', esc(i.freq))}${row('Authority', esc(lcAuthN(i.authority)) + (i.portal ? ` · <a href="${esc(i.portal)}" target="_blank" rel="noopener">portal</a>` : ''))}${row('Reference no.', esc(i.refNo))}${row('Issued / effective', bkDate(i.issue))}${row(kind === 'Filing' ? 'Due date' : 'Expiry date', (lcDue(i) ? bkDate(lcDue(i)) : '—') + (lcDue(i) ? (i.dateVerified ? ` ${pill('verified', 'ok')}${i.verifiedBy ? ' by ' + esc(i.verifiedBy) : ''}` : ` ${pill('not verified', 'warn')}`) : ''))}${row('Reminders from', bkDate(i.remindFrom))}${row('Owner / reviewer / approver', esc(`${i.owner} → ${i.reviewer} → ${i.approver}`))}${row('Applicability', esc(i.applic) + (i.na ? ` – ${esc(i.na.reason)} (approved by ${esc(i.na.appBy)} on ${bkDate(i.na.appOn)})` : '') + (i.naReq ? ` – <b>N/A requested</b> by ${esc(i.naReq.by)}: ${esc(i.naReq.reason)}` : ''))}${row('Rule / notes', esc((r || {}).rule || '') + (i.comments ? `<div class="small">${esc(i.comments)}</div>` : ''))}${row('Status', lcPill(st) + (flags.length ? ' ' + flags.map(f => `<span class="pill warn">${esc(f)}</span>`).join(' ') : ''))}</tbody></table>`; const files = `<h4>Documents</h4>${(i.files || []).length ? `<ul class="small">${i.files.map(f => `<li>📄 ${esc(f.name)} · ${esc(f.type)} · v${f.ver || 1} · ${esc(f.by)} · ${bkDate(String(f.t).slice(0, 10))}</li>`).join('')}</ul>` : '<p class="small muted">No document uploaded.</p>'}${(i.checklist || []).length ? `<h4>Required documents</h4><ul class="chk-list small">${i.checklist.map((c, k) => `<li><label><input type="checkbox" ${c.done ? 'checked' : ''} ${ed ? `data-act="lcChk" data-k="${esc(i.id)}~${k}"` : 'disabled'}> ${esc(c.t)}</label></li>`).join('')}</ul>` : ''}`; const vers = (i.versions || []).length ? `<h4>Versions</h4>${table('lcVer', [{ h: 'Ver', k: x => x.ver, t: 'num' }, { h: 'Ref. no.', k: x => x.refNo, t: 'text' }, { h: 'Issued', k: x => bkDate(x.issue), t: 'text' }, { h: 'Expiry / due', k: x => bkDate(x.expiry || x.due), t: 'text' }, { h: 'Closed by', k: x => `${x.by} · ${bkDate(String(x.t).slice(0, 10))}`, t: 'text', cls: 'small' }], i.versions, { compact: true })}` : ''; const hist = `<h4>History</h4><ul class="small">${(i.hist || []).slice().reverse().map(h => `<li>${tsLabel(h.t)} · ${esc(h.by)} · ${esc(h.e)}</li>`).join('')}</ul>`; const acts = [i.applic !== 'Not Applicable' && !t && lcp('task') && !['OneTime'].includes(kind) ? `<button class="btn primary" data-act="lcStartTask" data-k="${esc(i.id)}">Start renewal / filing task</button>` : '', t ? `<button class="btn" data-act="lcTaskOpen" data-k="${t.id}">Open task ${esc(t.no)} · ${esc(t.status)}</button>` : '', ed ? `<button class="btn" data-act="lcEditForm" data-k="${esc(i.id)}">Edit details</button>` : '', lcp('upload') ? `<button class="btn" data-act="lcUploadForm" data-k="${esc(i.id)}">Upload document</button>` : '', lcDue(i) && !i.dateVerified && lcp('verify') ? `<button class="btn" data-act="lcVerify" data-k="${esc(i.id)}">Verify date</button>` : '', i.applic !== 'Not Applicable' && !i.naReq && ed ? `<button class="btn" data-act="lcNaReq" data-k="${esc(i.id)}">Request “not applicable”</button>` : '', i.naReq && lcAdmin() ? `<button class="btn primary" data-act="lcNaDecide" data-k="${esc(i.id)}~ok">Approve N/A</button><button class="btn" data-act="lcNaDecide" data-k="${esc(i.id)}~no">Decline N/A</button>` : '', i.applic === 'Needs Review' && lcp('verify') ? `<button class="btn primary" data-act="lcApplicable" data-k="${esc(i.id)}">Confirm applicable</button>` : '', i.applic === 'Not Applicable' && lcAdmin() ? `<button class="btn" data-act="lcApplicable" data-k="${esc(i.id)}">Mark applicable again</button>` : '', lcAdmin() ? `<button class="btn danger" data-act="lcDelete" data-k="${esc(i.id)}">Delete</button>` : ''].filter(Boolean).join(''); modal(i.name, info + files + vers + hist, acts, true); }
