PAGES.lc_cal = { title: 'Compliance Calendar', mod: 'lc_cal', render() { const g = lcNoAccess(); if (g) return g; const ym = App.ui.lcYm || PROC_TODAY.slice(0, 7), days = hrMonthDays(ym), sub = lcSub(lcSelUnit()), kindF = App.ui.lcEvK || ''; const ev = lcEvents().filter(e => (!sub || sub.has(lcItem(e.id) ? lcItem(e.id).unit : (LCT().cases.find(c => c.id === e.id) || {}).unit)) && (!kindF || e.kind === kindF)); const inM = ev.filter(e => e.date.slice(0, 7) === ym); const first = new Date(days[0] + 'T00:00:00Z').getUTCDay(); const cells = Array.from({ length: first }, () => '<div class="cal-d off"></div>').concat(days.map(d => { const E = inM.filter(e => e.date === d); return `<div class="cal-d ${hrIsOff(d) ? 'off' : ''} ${E.length ? 'has' : ''} ${d === PROC_TODAY ? 'today' : ''}"><b>${+d.slice(8)}</b>${E.slice(0, 3).map(e => `<a href="#" class="small" data-act="${e.act}" data-k="${esc(e.id)}" title="${esc(e.title)}">${e.kind === 'Hearing' ? '⚖ ' : e.kind === 'Filing' ? '📄 ' : e.kind === 'Inspection' ? '🔍 ' : e.kind === 'Notice reply' ? '✉ ' : '🔁 '}${esc(e.title.length > 26 ? e.title.slice(0, 25) + '…' : e.title)}</a>`).join('')}${E.length > 3 ? `<em>+${E.length - 3} more</em>` : ''}</div>`; })); const ctr = `<label class="fld"><span>Month</span><select data-act="uiSel" data-k="lcYm">${rmMonths('2026-04', 15).map(m => `<option value="${m}" ${m === ym ? 'selected' : ''}>${rmPeriodLabel(m)}</option>`).join('')}</select></label><label class="fld"><span>Event type</span><select data-act="uiSel" data-k="lcEvK"><option value="">All</option>${['Renewal', 'Filing', 'Inspection', 'Hearing', 'Notice reply', 'Contract expiry'].map(k => `<option ${kindF === k ? 'selected' : ''}>${k}</option>`).join('')}</select></label>`; const upcoming = ev.filter(e => e.date >= PROC_TODAY).slice(0, 60); return `${lcBar(ctr, { noSearch: true })}${card(`Calendar · ${rmPeriodLabel(ym)} · ${inM.length} events`, `<div class="cal">${['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(d => `<div class="small muted" style="text-align:center">${d}</div>`).join('')}${cells.join('')}</div><p class="small muted">🔁 renewal · 📄 filing · 🔍 inspection · ⚖ hearing · ✉ notice reply</p>`)}${card('Upcoming events', table('lcEv', [{ h: 'Date', k: e => bkDate(e.date), t: 'text', x: e => e.date }, { h: 'Type', k: e => e.kind, t: 'text' }, { h: 'Event', k: e => `<a href="#" data-act="${e.act}" data-k="${esc(e.id)}">${esc(e.title)}</a>${e.unv ? ' <span class="small amber">(date unverified)</span>' : ''}`, t: 'html', x: e => e.title }, { h: 'Where', k: e => e.where, t: 'text', cls: 'small' }, { h: 'Status', k: e => lcPill(e.st), t: 'html', x: e => e.st }], upcoming, { compact: true, limit: 60 }), { right: exportBtns('lcEv', 'lc_cal') })}`; } };
/* ---------- renewals & filings (tasks) ---------- */
const lcTaskOf = id => LCT().tasks.find(t => t.id === id);
PAGES.lc_renew = { title: 'Renewals & Filings', mod: 'lc_renew', render() { const g = lcNoAccess(); if (g) return g; const sub = lcSub(lcSelUnit()), mine = new Set(lcUnitsMine()), q = lcQ(); const all = LCT().tasks.filter(t => { const i = lcItem(t.item); return i && mine.has(i.unit) && (!sub || sub.has(i.unit)) && (!q || `${t.no} ${i.name} ${lcPath(lcU(i.unit))} ${t.assignee}`.toLowerCase().includes(q)); }); const tab = pcTab('lct', 'open'); const F = { open: t => ['Open', 'In Progress', 'Corrections'].includes(t.status), review: t => t.status === 'Legal review', fee: t => t.status === 'Fee approval' || (t.fee && t.fee.status === 'With Finance'), sub: t => t.status === 'Submitted', done: t => ['Closed', 'Cancelled'].includes(t.status) }; const tabs = pcTabs('lct', [['open', 'Open / in progress', all.filter(F.open).length], ['review', 'Legal review', all.filter(F.review).length], ['fee', 'Fee approval (Finance)', all.filter(F.fee).length], ['sub', 'Submitted – awaiting certificate', all.filter(F.sub).length], ['done', 'Closed / cancelled', all.filter(F.done).length]], 'open'); const rows = all.filter(F[tab] || F.open).sort((a, b) => (a.due || '').localeCompare(b.due || '')); const cols = [{ h: 'Task', k: t => t.no, t: 'text' }, { h: 'Requirement', k: t => { const i = lcItem(t.item); return `${esc(i.name)}<div class="small muted">${esc(lcShort(lcU(i.unit)))}</div>`; }, t: 'html', x: t => (lcItem(t.item) || {}).name }, { h: 'Due', k: t => bkDate(t.due), t: 'text', x: t => t.due || '' }, { h: 'Days', k: t => lcDaysCell({ due: t.due }), t: 'html', x: t => t.due ? lcDays(t.due) : 0 }, { h: 'Checklist', k: t => `${t.checklist.filter(c => c.done).length} / ${t.checklist.length}`, t: 'text' }, { h: 'Assignee', k: t => t.assignee, t: 'text', cls: 'small' }, { h: 'Fee', k: t => t.fee ? `${INR(t.fee.amount)} · ${t.fee.status}` : '—', t: 'text', cls: 'small' }, { h: 'Status', k: t => lcPill(t.status), t: 'html', x: t => t.status }]; return `${lcBar()}${card('Renewal & filing tasks', tabs + table('lcTasks', cols, rows, { rowAct: 'lcTaskOpen', rowKey: t => t.id, compact: true, limit: 100, empty: 'No tasks in this list.' }), { right: exportBtns('lcTasks', 'lc_renew'), sub: 'Workflow: owner prepares (checklist) → Legal review → fee request to Finance (if any) → submission to the authority → renewed certificate uploaded and verified by Legal (new version). Reviewer must be different from the person who sent the task.' })}`; } };
function lcTaskDoc(t) { const i = lcItem(t.item) || {}, u = App.user, canWork = lcp('task') && !['Closed', 'Cancelled'].includes(t.status), isLegal = lcp('verify'), isFin = lcp('fee'); const row = (k, vv) => `<tr><th>${k}</th><td>${vv == null || vv === '' ? '—' : vv}</td></tr>`; const info = `<table class="kv"><tbody>${row('Requirement', `<a href="#" data-act="lcOpen" data-k="${esc(i.id)}">${esc(i.name)}</a>`)}${row('Unit', esc(lcPath(lcU(i.unit))))}${row('Authority', esc(lcAuthN(i.authority)) + (i.portal ? ` · <a href="${esc(i.portal)}" target="_blank" rel="noopener">portal</a>` : ''))}${row('Current expiry / due', bkDate(t.due))}${row('Assignee', esc(t.assignee))}${row('Created', `${tsLabel(t.created)} · ${esc(t.by)}`)}${row('Status', lcPill(t.status) + (t.reviewed ? ' ' + pill('reviewed by ' + t.reviewed.by, 'ok') : ''))}${t.fee ? row('Fee', `${INR(t.fee.amount)} to ${esc(t.fee.payee)} · ref ${esc(t.fee.ref || '—')} · due ${bkDate(t.fee.due)} · ${lcPill(t.fee.status)}${t.fee.jv ? ' · posted ' + esc(t.fee.jv) : ''}`) : ''}${t.sub ? row('Submission', `${bkDate(t.sub.date)} · application ${esc(t.sub.appNo)} · challan ${esc(t.sub.challan || '—')} · ack ${esc(t.sub.ack || '—')}`) : ''}</tbody></table>`; const chk = `<h4>Checklist</h4><ul class="chk-list small">${t.checklist.map((c, k) => `<li><label><input type="checkbox" ${c.done ? 'checked' : ''} ${canWork ? `data-act="lcTChk" data-k="${t.id}|${k}"` : 'disabled'}> ${esc(c.t)}</label></li>`).join('')}</ul>`; const notes = `<h4>Notes &amp; documents</h4><ul class="small">${(t.notes || []).slice().reverse().map(n => `<li>${tsLabel(n.t)} · ${esc(n.by)} · ${esc(n.text)}</li>`).join('') || '<li class="muted">No notes.</li>'}</ul>${(t.files || []).length ? `<ul class="small">${t.files.map(f => `<li>📄 ${esc(f.name)} · ${esc(f.type)} · ${esc(f.by)} · ${tsLabel(f.t)}</li>`).join('')}</ul>` : ''}${canWork ? `<label class="fld"><span>Add note</span><input id="lcNote" placeholder="Progress note…"></label><button class="btn sm" data-act="lcTNote" data-k="${t.id}">Add note</button>` : ''}`; const log = (t.log || []).length ? `<h4>Activity</h4><ul class="small">${t.log.slice().reverse().map(l => `<li>${tsLabel(l.t)} · ${esc(l.by)} · ${esc(l.e)}${l.remark ? ' – ' + esc(l.remark) : ''}</li>`).join('')}</ul>` : ''; const A = []; if (canWork) { if (['Open', 'In Progress', 'Corrections'].includes(t.status)) { A.push(`<button class="btn primary" data-act="lcTMove" data-k="${t.id}|Legal review">Send for legal review</button>`); if (!t.fee || t.fee.status === 'Rejected') A.push(`<button class="btn" data-act="lcFeeForm" data-k="${t.id}">Request fee payment</button>`); A.push(`<button class="btn" data-act="lcSubmitForm" data-k="${t.id}">Record submission</button>`); } if (t.status === 'Legal review' && isLegal) { if (t.sentBy === u.name) A.push(`<span class="small muted">Reviewer must be different from the sender.</span>`); else A.push(`<button class="btn primary" data-act="lcTMove" data-k="${t.id}|Reviewed">Reviewed – OK to proceed</button><button class="btn" data-act="lcTMove" data-k="${t.id}|Corrections">Return for corrections</button>`); } if (t.status === 'Fee approval' && isFin) A.push(`<button class="btn primary" data-act="lcFeeDecide" data-k="${t.id}|ok">Approve &amp; pay fee</button><button class="btn" data-act="lcFeeDecide" data-k="${t.id}|no">Reject fee request</button>`); if (t.status === 'Fee approval' && !isFin) A.push('<span class="small muted">Awaiting Finance approval of the fee.</span>'); if (t.status === 'Submitted') { if (isLegal) A.push(`<button class="btn primary" data-act="lcCloseForm" data-k="${t.id}">Verify renewed document &amp; close</button>`); else A.push('<span class="small muted">Awaiting Legal verification of the renewed document.</span>'); A.push(`<button class="btn" data-act="lcTUploadForm" data-k="${t.id}">Upload document</button>`); } if (lcp('upload') && t.status !== 'Submitted') A.push(`<button class="btn" data-act="lcTUploadForm" data-k="${t.id}">Upload document</button>`); if (lcAdmin() || t.by === u.name) A.push(`<button class="btn danger" data-act="lcTMove" data-k="${t.id}|Cancelled">Cancel task</button>`); } modal(`${t.no} · ${i.name}`, info + chk + notes + log, A.join(''), true); }
/* ---------- cases & notices ---------- */
PAGES.lc_cases = { title: 'Cases & Notices', mod: 'lc_cases', render() { const g = lcNoAccess(); if (g) return g; const sub = lcSub(lcSelUnit()), mine = new Set(lcUnitsMine()), q = lcQ(), tab = pcTab('lcc', 'open'); const all = LCT().cases.filter(c => !c.deleted && mine.has(c.unit) && (!sub || sub.has(c.unit)) && (!q || `${c.no} ${c.title} ${c.caseNo} ${c.forum} ${c.parties} ${c.advocate}`.toLowerCase().includes(q))); const open = c => !/Closed|Settled|Disposed/.test(c.status); const rows = all.filter(c => tab === 'open' ? open(c) : tab === 'notice' ? c.type === 'Notice' : !open(c)); const nextH = c => (c.hearings || []).filter(h => !h.outcome).map(h => h.date).sort()[0] || ''; const cols = [{ h: 'Ref.', k: c => c.no, t: 'text' }, { h: 'Type', k: c => c.type, t: 'text' }, { h: 'Matter', k: c => `<b>${esc(c.title)}</b><div class="small muted">${esc(c.caseNo)} · ${esc(c.forum)}</div>`, t: 'html', x: c => c.title }, { h: 'Unit', k: c => lcShort(lcU(c.unit)), t: 'text', cls: 'small' }, { h: 'Parties', k: c => c.parties, t: 'text', cls: 'small' }, { h: 'Advocate', k: c => c.advocate || '—', t: 'text', cls: 'small' }, { h: 'Filed / received', k: c => bkDate(c.filed), t: 'text', x: c => c.filed }, { h: 'Next hearing / reply due', k: c => { const d = c.type === 'Notice' && c.noticeDue && open(c) ? c.noticeDue : nextH(c); return d ? `${bkDate(d)} ${lcDaysCell({ due: d })}` : '—'; }, t: 'html', x: c => nextH(c) || c.noticeDue || '' }, { h: 'Status', k: c => lcPill(c.status), t: 'html', x: c => c.status }]; const tabs = pcTabs('lcc', [['open', 'Open matters', all.filter(open).length], ['notice', 'Notices', all.filter(c => c.type === 'Notice').length], ['closed', 'Closed / disposed', all.filter(c => !open(c)).length]], 'open'); return `${lcBar(`<div class="btnrow">${lcp('case') ? `<button class="btn primary" data-act="lcCaseForm" data-k="">New case / notice</button>` : ''}</div>`)}${card('Legal matters', tabs + table('lcCases', cols, rows, { rowAct: 'lcCaseOpen', rowKey: c => c.id, compact: true, limit: 100, empty: 'No matters in this list.' }), { right: exportBtns('lcCases', 'lc_cases'), sub: 'Court cases, consumer complaints, labour disputes, statutory notices and show-cause notices with hearing dates, advocate details and outcomes. Hearings and notice-reply deadlines appear on the compliance calendar.' })}`; } };
function lcCaseDoc(c) { const ed = lcp('case'), open = !/Closed|Settled|Disposed/.test(c.status); const row = (k, vv) => `<tr><th>${k}</th><td>${vv == null || vv === '' ? '—' : vv}</td></tr>`; const info = `<table class="kv"><tbody>${row('Type', esc(c.type))}${row('Unit', esc(lcPath(lcU(c.unit))))}${row('Forum / authority', esc(c.forum))}${row('Case / notice no.', esc(c.caseNo))}${row('Parties', esc(c.parties))}${row('Advocate / consultant', esc(c.advocate) + (c.advPhone ? ' · ' + esc(c.advPhone) : ''))}${row('Filed / received', bkDate(c.filed))}${c.type === 'Notice' ? row('Reply due', c.noticeDue ? bkDate(c.noticeDue) + ' ' + lcDaysCell({ due: c.noticeDue }) : '—') : ''}${row('Summary', esc(c.summary))}${row('Status', lcPill(c.status))}${row('Documents', (c.files || []).map(f => '📄 ' + esc(typeof f === 'string' ? f : f.name)).join(' · '))}</tbody></table>`; const hear = `<h4>Hearings</h4>${table('lcHear', [{ h: 'Date', k: h => bkDate(h.date), t: 'text', x: h => h.date }, { h: 'Purpose', k: h => h.purpose, t: 'text' }, { h: 'Outcome', k: h => h.outcome ? esc(h.outcome) : (ed && open ? `<button class="btn sm" data-act="lcHearOut" data-k="${c.id}|${h.date}">Record outcome</button>` : '<span class="muted">pending</span>'), t: 'html', x: h => h.outcome || '' }], (c.hearings || []).slice().sort((a, b) => a.date.localeCompare(b.date)), { compact: true, empty: 'No hearings recorded.' })}`; const log = (c.log || []).length ? `<h4>Activity</h4><ul class="small">${c.log.slice().reverse().map(l => `<li>${tsLabel(l.t)} · ${esc(l.by)} · ${esc(l.e)}${l.remark ? ' – ' + esc(l.remark) : ''}</li>`).join('')}</ul>` : ''; const A = ed ? [`<button class="btn" data-act="lcCaseForm" data-k="${c.id}">Edit</button>`, open ? `<button class="btn" data-act="lcHearForm" data-k="${c.id}">Add hearing</button>` : '',  lcAdmin() ? `<button class="btn danger" data-act="lcCaseDelete" data-k="${c.id}">Delete</button>` : ''].filter(Boolean).join('') : ''; const stForm = ed && open ? `<h4>Update status</h4><div class="grid3">${pcFld('New status', pcSel('lcCaseSt', LC_CASE_ST, c.status))}<div class="btnrow" style="align-self:end"><button class="btn primary" data-act="lcCaseStatus" data-k="${c.id}">Update status</button></div></div>` : ''; modal(`${c.no} · ${c.title}`, info + hear + stForm + log, A, true); }
