  lcCaseDelete(t) { if (!lcAdmin()) return toast('Only Legal Admin can delete.', 'bad'); askReason('Delete matter', 'Reason (recorded in the audit trail).', r => { if (!r) return toast('Reason is required.', 'bad'); const tx = Store.clone(LCT()); const c = tx.cases.find(x => x.id === t.dataset.k); if (!c) return; c.deleted = true; lcLog(tx, 'Matter deleted', `${c.no} · ${c.title}`, r); lcSave(tx, 'Deleted.'); closeModal(); }); },
